import{_ as l,l as n,o as t,c as i,v as e,p as s,x as o,d,i as u,S as E}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"结构性票据拆解","description":"","frontmatter":{"title":"结构性票据拆解","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/structured-notes.md","filePath":"quant/structured-notes.md","lastUpdated":1789023840000}'),p={name:"quant/structured-notes.md"};function c(A,a,h,_,q,B){const r=n("Mermaid");return t(),i("div",null,[a[1]||(a[1]=e('<h1 id="结构性票据拆解" tabindex="-1">结构性票据拆解 <a class="header-anchor" href="#结构性票据拆解" aria-label="Permalink to &quot;结构性票据拆解&quot;">​</a></h1><div class="epigraph"><p>结构票据是零息债加一包期权；票息是期权费的分期，不是债券信用利差的另一种写法。</p><footer>—— 结构产品拆解见 Fabozzi 对 structured notes 的综述；障碍与自动赎回条款对照本课序前几课</footer></div><p><a href="/quant/warrants-eso">上一课</a>把覆盖权证、公司权证与 ESO 分开：可对冲香草、稀释、作废与过早行权不是同一套希腊值。缺口是零售与私行看到的「票息 ×%、挂钩指数、有保护」——簿上应看到零息债、香草、数字、障碍、autocall、cliquet 的组合。本课把拆解当成强制步骤。不重讲 Hull–White 行为树。后课 AAD 默认已经读完：不拆开就无法把利率风险与股权风险交给不同的台。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一张「保本看涨」= 零息债 + 虚值看涨（或看涨价差）。一张凤凰/雪球 = 债 + 卖出离散障碍与敲入看跌，票息是收费。问题不是再给雪球定价——<a href="/quant/autocallable">自动赎回</a> 与 <a href="/quant/snowball-pricing">雪球</a> 已写——而是：<strong>发行价 100 里有多少是债、多少是期权费、多少是发行与对冲利润。</strong> 不拆开，就无法把利率风险交给利率台、把股权风险交给期权台，也无法解释「票息为什么比存款高」。</p><p>信用：票据是发行人的无抵押债。股权结构再漂亮，仍承担发行人违约。把结构票据当「指数理财」，漏掉的是 <a href="/quant/cva-lite">CVA</a> 那一层，后课 XVA 桥会再接。</p><h3 id="拆解必须与条款时钟一致" tabindex="-1">拆解必须与条款时钟一致 <a class="header-anchor" href="#拆解必须与条款时钟一致" aria-label="Permalink to &quot;拆解必须与条款时钟一致&quot;">​</a></h3><p>观察日、记忆票息、最差表现、Quanto 结算、提前赎回权（发行人 call）每一条都对应前面某课的零件。拆错时钟（把离散敲出当连续障碍，把 quanto 当普通外国期权）比选错波动模型更致命。先画支付树，再选模型。</p><p><span class="marginnote">发行利润来自买卖价差、微笑上卖贵的那一侧、以及零售对路径概率的错误直觉。估值引擎应用卖方曲面，而不是用历史已实现波动去「解释票息」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>步骤：(1) 把确定性支付贴现成债（用发行人曲线或融资曲线，视是否有抵押）；(2) 把或有支付映射到已有期权类型；(3) 在与香草一致的模型下估值，检查发行价与模型价的差；(4) 希腊值按拆开后的腿加总，再对冲。多标的 worst-of 先当彩虹/篮子，再叠加障碍。利率挂钩结构（区间计息、CMS 陡峭）用后课 caps/floors/swaptions，不要用股权局部波动去估 CMS。</p><p>文档与确认书优先于销售材料。销售材料里的情景不是风险中性概率。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>投资者买的是债的信用加卖出的期权包。市场好时票息像「超额收益」，其实是期权费摊还；市场坏时敲入或保本失效，才露出卖出的那条腿。发行人反向持有期权包并对冲，利润是收费减对冲成本减资本。拆解的意义是让这三层能分开盯市，而不是把整张票当一个「收益率产品」去比存款。</p>',14)),(t(),s(E,null,{default:o(()=>[u(r,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20Note%5B%22%E7%BB%93%E6%9E%84%E7%A5%A8%E6%8D%AE%20%E5%8F%91%E8%A1%8C%E4%BB%B7%22%5D%20--%3E%20Bond%5B%22%E9%9B%B6%E6%81%AF%E5%80%BA%20%E5%8F%91%E8%A1%8C%E4%BA%BA%E4%BF%A1%E7%94%A8%22%5D%0A%20%20Note%20--%3E%20Opt%5B%22%E6%9C%9F%E6%9D%83%E5%8C%85%20%E9%A6%99%E8%8D%89%20%E6%95%B0%E5%AD%97%20%E9%9A%9C%E7%A2%8D%20%E9%87%8D%E7%BD%AE%22%5D%0A%20%20Opt%20--%3E%20Fee%5B%22%E7%A5%A8%E6%81%AF%E6%9D%A5%E8%87%AA%E5%8D%96%E5%87%BA%E6%9C%9F%E6%9D%83%22%5D%0A%20%20Bond%20--%3E%20Credit%5B%22%E8%BF%9D%E7%BA%A6%E6%98%AF%E5%8F%A6%E4%B8%80%E6%9D%A1%E8%85%BF%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>提前赎回、展期、发行人置换权会让拆解随时间变形。监管与适当性限制销售对象，不改变拆解代数，但改变你能不能用批发曲面去解释零售价差。跨境票据还有税务与 FX，见 <a href="/quant/quanto-options">quanto</a>。</p><p>本课不提供销售话术，也不讨论把结构改写成规避适当性的包装。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>结构票据 = 债 + 期权包；票息是期权费，不是信用利差的别名。</li><li>拆解必须对齐观察时钟与支付类型；错时钟比错模型更严重。</li><li>发行人信用是单独一条腿，后续接到 XVA。</li><li>出处：结构票据拆解见 Fabozzi 相关综述；零件分别见本课序障碍、数字、autocall、cliquet。</li></ul>',5))])}const D=l(p,[["render",c]]);export{m as __pageData,D as default};
